<?php require_once __DIR__ . '/../bootstrap.php'; $user=require_auth(); $i=body(); if(!clean($i['title']??'')||!clean($i['activity']??'')||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$i['log_date']??'')) respond(false,'Title, date, and activity are required.',[],422); $s=$pdo->prepare('INSERT INTO log_entries(user_id,title,log_date,time_in,time_out,activity,location,category,remarks,status) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$user['id'],clean($i['title']),$i['log_date'],$i['time_in']??null,$i['time_out']??null,clean($i['activity']),clean($i['location']??'')?:null,clean($i['category']??'Other'),clean($i['remarks']??''),$i['status']??'Completed']);respond(true,'Log entry created successfully.',['id'=>$pdo->lastInsertId()],201);
